# Verify round-trip
def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    background = grid[0][0]
    result = [[background for _ in range(cols)] for _ in range(rows)]
    inp = [(r, c, grid[r][c]) for r in range(rows) for c in range(cols) 
                if grid[r][c] != background]
    for r, c, val in inp:
        if val == 1:
            ad = r + c
            for cr in range(rows):
                cc = ad - cr
                if 0 <= cc < cols and grid[cr][cc] == background:
                    result[cr][cc] = 1
        elif val == 6:
            sd = r - c
            for cc in range(cols):
                cr = sd + cc
                if 0 <= cr < rows and grid[cr][cc] == background:
                    result[cr][cc] = 6
    return result

